// The global 30-minute timeout as per ADR-001. 30 minutes in milliseconds.
const SESSION_TIMEOUT_MS = 30 * 60 * 1000;

/**
 * Returns the number of milliseconds remaining until the session expires.
 * If the session is already expired, returns 0.
 *
 * - If session.lastActivityAt is in the future or invalid, treat as 0 as a safety.
 * - If now is not provided, use Date.now()
 */
export function remainingSessionMs(session: Session, now?: number): number {
  const current = typeof now === 'number' ? now : Date.now();
  // Validate inputs
  if (!Number.isFinite(current)) {
    return 0;
  }
  const last = Number.isFinite(session?.lastActivityAt) ? session.lastActivityAt : NaN;
  if (!Number.isFinite(last)) {
    return 0;
  }
  const elapsed = current - last;
  if (elapsed < 0) {
    // If clock drift or future lastActivityAt, treat as not expired yet.
    return Math.max(0, SESSION_TIMEOUT_MS + elapsed);
  }
  const remaining = SESSION_TIMEOUT_MS - elapsed;
  return remaining > 0 ? remaining : 0;
}

