// Password reset helper module
// Provides a deterministic, side-effect-free creation of a password reset request
// Rules:
// - Trim and lowercase the input email
// - If the resulting email is empty, reject by returning null
// - Otherwise return an object with email and expiresAt = now + 15 minutes

export type PasswordResetRequest = {
  email: string;
  expiresAt: number;
};

// 15 minutes in milliseconds
const FIFTEEN_MINUTES_MS = 15 * 60 * 1000;

/**
 * Creates a password reset request for the given email.
 * - email is trimmed and lowercased
 * - if the trimmed email is empty, returns null to indicate rejection
 * - otherwise returns { email, expiresAt }
 * @param email input email address
 * @param now current time in milliseconds since epoch
 */
export function createPasswordResetRequest(email: string, now: number): PasswordResetRequest | null {
  const normalized = (email ?? "").trim().toLowerCase();
  if (normalized.length === 0) {
    return null;
  }
  return {
    email: normalized,
    expiresAt: now + FIFTEEN_MINUTES_MS,
  };
}

